import pytest
from candidate import fruit_distribution


class TestFruitDistribution:
    def test_normal_case_basic(self):
        assert fruit_distribution("5 apples and 6 oranges", 19) == 8

    def test_normal_case_zero_apples(self):
        assert fruit_distribution("0 apples and 1 oranges", 3) == 2

    def test_normal_case_large_total(self):
        assert fruit_distribution("2 apples and 3 oranges", 100) == 95

    def test_normal_case_large_apples(self):
        assert fruit_distribution("100 apples and 1 oranges", 120) == 19

    def test_zero_mango_fruits(self):
        assert fruit_distribution("5 apples and 5 oranges", 10) == 0

    def test_zero_apples_zero_oranges(self):
        assert fruit_distribution("0 apples and 0 oranges", 10) == 10

    def test_single_digit_numbers(self):
        assert fruit_distribution("1 apples and 2 oranges", 10) == 7

    def test_three_digit_numbers(self):
        assert fruit_distribution("123 apples and 456 oranges", 1000) == 421

    def test_total_equals_one(self):
        assert fruit_distribution("1 apples and 0 oranges", 1) == 0

    def test_negative_mango_count(self):
        assert fruit_distribution("15 apples and 16 oranges", 10) == -21

    def test_large_numbers(self):
        assert fruit_distribution("1000 apples and 2000 oranges", 5000) == 2000

    def test_extra_spaces_in_string(self):
        assert fruit_distribution("  5 apples and 6 oranges  ", 19) == 8

    def test_single_space_separation(self):
        assert fruit_distribution("1 apples and 2 oranges", 9) == 6

    def test_returns_int_type(self):
        result = fruit_distribution("5 apples and 6 oranges", 19)
        assert isinstance(result, int)

    def test_empty_string_returns_n(self):
        assert fruit_distribution("", 5) == 5

    def test_string_with_no_digits(self):
        assert fruit_distribution("apples and oranges", 10) == 10

    def test_string_with_only_apples_mentioned(self):
        assert fruit_distribution("3 apples", 10) == 7

    def test_string_with_only_oranges_mentioned(self):
        assert fruit_distribution("4 oranges", 10) == 6

    def test_none_string_raises_error(self):
        with pytest.raises(Exception):
            fruit_distribution(None, 10)

    def test_none_total_raises_error(self):
        with pytest.raises(Exception):
            fruit_distribution("5 apples and 6 oranges", None)

    def test_both_none_raises_error(self):
        with pytest.raises(Exception):
            fruit_distribution(None, None)

    def test_float_total(self):
        assert fruit_distribution("5 apples and 6 oranges", 19.5) == 8.5

    def test_zero_total(self):
        assert fruit_distribution("5 apples and 6 oranges", 0) == -11

    def test_very_large_total(self):
        assert fruit_distribution("1 apples and 1 oranges", 999999) == 999997

    def test_result_is_subtraction_not_division(self):
        assert fruit_distribution("2 apples and 3 oranges", 10) == 5

    def test_apples_and_oranges_both_single_digit(self):
        assert fruit_distribution("9 apples and 9 oranges", 20) == 2

    def test_string_with_numbers_but_different_words(self):
        assert fruit_distribution("5 pears and 6 lemons", 19) == 8

    def test_multiple_spaces_between_words(self):
        assert fruit_distribution("5   apples   and   6   oranges", 19) == 8
